/**
 * 표 객체(ACAD_TABLE) ↔ 표 정의.
 *
 * 모델의 ACAD_TABLE은 행·열 크기와 셀 문자만 가진다. 병합·행 종류·셀 정렬·준 행 높이·셀 배경 채우기(31차)·셀 문자 높이·문자 색(32차)·셀 문자 스타일(33차)·
 * 셀 잠금(34차)은 확장 자료 OPENCAD_TABLE에 남긴다(DXF·DWG 모두 그대로 저장된다). 셀 잠금은 DWG R2010+ 셀 상태로도 쓰고 읽는다(DXF 참조에는 코드가 없다). AutoCAD가 쓴 표는 원본 태그의 셀 병합(173·175·176)과
 * 셀 정렬(170), 셀 배경 채우기(63·283), 셀 문자 높이(140)·문자 색(64)·문자 스타일(7)을 읽는다. 표를 블록 참조로 저장한 파일(DWG 쓰기)도 확장 자료가 있으면 다시 표로 읽을 수 있다.
 */
import { TABLE_EMPTY_CELLS, TABLE_MERGE_RATIO, tableSizeOk } from '../../core/limits';
import type { CadColor, CadDocument, Entity, InsertEntity, RawTag, TableEntity, XData, XDataItem } from '../../core/model';
import { tableKey } from '../../core/model';
import type { CellKind, TableStyle } from './style';
import { findTableStyle, isMetric, defaultTableStyle, type TableStyleEntry } from './style';
import type { CellData, Merge, TableData } from './model';
import { decodeCadEscapes } from '../../core/codepage';

export const TABLE_APP = 'OPENCAD_TABLE';

const KIND_CODE: Record<CellKind, number> = { data: 0, title: 1, header: 2 };
const CODE_KIND: CellKind[] = ['data', 'title', 'header'];

/** 확장 자료 문자열 한 조각의 최대 글자 수(DXF 1000 그룹 255바이트 제한 안쪽) */
const CHUNK = 80;
/** 셀 문자를 확장 자료에 담는 최대 글자 수(AutoCAD 확장 자료 16KB 제한 안쪽) */
const MAX_TEXT = 4000;

function chunks(s: string): string[] {
  const out: string[] = [];
  const cps = Array.from(s);
  for (let i = 0; i < cps.length; i += CHUNK) out.push(cps.slice(i, i + CHUNK).join(''));
  return out.length ? out : [''];
}

export function encodeTableXData(t: TableData): XData {
  const it: XDataItem[] = [];
  const s = (v: string) => it.push({ code: 1000, value: v });
  const i32 = (v: number) => it.push({ code: 1071, value: Math.round(v) });
  const r = (v: number) => it.push({ code: 1040, value: v });
  s('OPENCAD_TABLE 1');
  s('size');
  i32(t.rows);
  i32(t.cols);
  s('rowh');
  i32(t.rows);
  t.rowHeights.forEach(r);
  s('baseh');
  i32(t.rows);
  t.baseRowHeights.forEach(r);
  s('colw');
  i32(t.cols);
  t.colWidths.forEach(r);
  s('kinds');
  i32(t.rows);
  t.rowKinds.forEach((k) => i32(KIND_CODE[k]));
  s('merge');
  i32(t.merges.length);
  for (const m of t.merges) (i32(m.row), i32(m.col), i32(m.rows), i32(m.cols));
  const aligned = t.cells.map((c, i) => [i, c.align ?? 0] as const).filter(([, a]) => a >= 1 && a <= 9);
  s('align');
  i32(aligned.length);
  for (const [i, a] of aligned) (i32(i), i32(a));
  const texts = t.cells.map((c, i) => [i, c.text] as const).filter(([, x]) => x);
  const total = texts.reduce((a, [, x]) => a + x.length, 0);
  if (total <= MAX_TEXT) {
    s('text');
    i32(texts.length);
    for (const [i, x] of texts) {
      const parts = chunks(x);
      i32(i);
      i32(parts.length);
      parts.forEach(s);
    }
  }
  // 31차 셀 배경 채우기 재지정: 맨 끝에 둔다(이전 판의 읽기는 모르는 묶음에서 멈추므로 앞의 묶음을 그대로 읽는다).
  // 같은 채우기가 이어진 셀(행 우선 번호)을 한 묶음으로: 시작 번호, 개수, 색인(채우지 않음 −1), 트루컬러(없으면 −1)
  const runs: [number, number, number, number][] = [];
  t.cells.forEach((c, i) => {
    if (c.fill === undefined) return;
    const aci = c.fill ? c.fill.aci : -1;
    const rgb = c.fill && c.fill.rgb !== undefined ? c.fill.rgb & 0xffffff : -1;
    const last = runs[runs.length - 1];
    if (last && last[0] + last[1] === i && last[2] === aci && last[3] === rgb) last[1]++;
    else runs.push([i, 1, aci, rgb]);
  });
  if (runs.length) {
    s('fill');
    i32(runs.length);
    for (const run of runs) run.forEach(i32);
  }
  // 32차 셀 문자 높이·문자 색 재지정: 채우기 뒤(31차까지의 읽기는 여기서 멈추고 앞의 묶음을 그대로 읽는다). 재지정이 없으면 묶음도 없다(31차와 같은 확장 자료).
  // 문자 높이: 같은 높이가 이어진 셀을 한 묶음 — 시작 번호, 개수, 높이(실수)
  const hruns: [number, number, number][] = [];
  t.cells.forEach((c, i) => {
    if (c.height === undefined || !(c.height > 0)) return;
    const last = hruns[hruns.length - 1];
    if (last && last[0] + last[1] === i && last[2] === c.height) last[1]++;
    else hruns.push([i, 1, c.height]);
  });
  if (hruns.length) {
    s('theight');
    i32(hruns.length);
    for (const [start, count, v] of hruns) (i32(start), i32(count), r(v));
  }
  // 문자 색: 같은 색이 이어진 셀을 한 묶음 — 시작 번호, 개수, 색인(ByBlock 0·ByLayer 256), 트루컬러(없으면 −1)
  const cruns: [number, number, number, number][] = [];
  t.cells.forEach((c, i) => {
    if (!c.color) return;
    const aci = c.color.aci;
    const rgb = c.color.rgb !== undefined ? c.color.rgb & 0xffffff : -1;
    const last = cruns[cruns.length - 1];
    if (last && last[0] + last[1] === i && last[2] === aci && last[3] === rgb) last[1]++;
    else cruns.push([i, 1, aci, rgb]);
  });
  if (cruns.length) {
    s('tcolor');
    i32(cruns.length);
    for (const run of cruns) run.forEach(i32);
  }
  // 33차 셀 문자 스타일 재지정: 문자 색 뒤(32차까지의 읽기는 여기서 멈춘다). 같은 이름이 이어진 셀을 한 묶음 — 시작 번호, 개수, 이름 조각 수, 이름 조각(셀 문자와 같은 조각)
  it.push(...textStyleGroup(new Map(t.cells.flatMap((c, i): [number, string][] => (c.textStyle ? [[i, c.textStyle]] : [])))));
  // 34차 셀 잠금: 문자 스타일 뒤(33차까지의 읽기는 여기서 멈춘다). 같은 잠금이 이어진 셀을 한 묶음 — 시작 번호, 개수, 잠금 비트(1 내용, 4 서식)
  const lruns: [number, number, number][] = [];
  t.cells.forEach((c, i) => {
    const v = (c.lock ?? 0) & 5;
    if (!v) return;
    const last = lruns[lruns.length - 1];
    if (last && last[0] + last[1] === i && last[2] === v) last[1]++;
    else lruns.push([i, 1, v]);
  });
  if (lruns.length) {
    s('lock');
    i32(lruns.length);
    for (const run of lruns) run.forEach(i32);
  }
  return { app: TABLE_APP, items: it };
}

export interface DecodedTable {
  rows: number;
  cols: number;
  rowHeights?: number[];
  baseRowHeights?: number[];
  colWidths?: number[];
  rowKinds?: CellKind[];
  merges: Merge[];
  aligns: Map<number, number>;
  texts?: Map<number, string>;
  /** 셀 배경 채우기 재지정(31차, 채우지 않음은 null) */
  fills?: Map<number, CadColor | null>;
  /** 셀 문자 높이·문자 색 재지정(32차) */
  heights?: Map<number, number>;
  colors?: Map<number, CadColor>;
  /** 셀 문자 스타일 재지정(33차 — 이름) */
  textStyles?: Map<number, string>;
  /** 셀 잠금 비트(34차 — 1 내용, 4 서식) */
  locks?: Map<number, number>;
  /** 읽은 묶음마다 확장 자료 항목 안의 자리 [시작, 끝)(33차 — 문자 스타일 이름 바꾸기가 tstyle 묶음만 바꿔 넣을 때 쓴다) */
  spans: Map<string, [number, number]>;
}

/** 표 자료를 푼다. head면 머리 값만 본다: 셀 묶음을 펼치지 않고 병합을 거르지 않는다(표인지 묻는 자리는 클릭마다 객체마다 부른다) */
export function decodeTableXData(x: XData | undefined, head = false): DecodedTable | null {
  if (!x || x.app.toUpperCase() !== TABLE_APP) return null;
  const items = x.items;
  let i = 0;
  const next = (): XDataItem | undefined => items[i++];
  const int = (): number => {
    const v = next()?.value;
    return typeof v === 'number' ? Math.round(v) : Number(v) || 0;
  };
  const real = (): number => {
    const v = next()?.value;
    return typeof v === 'number' ? v : Number(v) || 0;
  };
  /** 묶음의 항목 수. 항목마다 확장 자료 칸을 하나 이상 쓰므로 남은 칸 수까지만 믿는다(값 하나로 수억 칸을 잡지 않게) */
  const size = (): number => Math.min(int(), items.length - i);
  /**
   * 셀 묶음(시작, 개수) 하나를 표 크기 안에서 돈다. 셀 묶음은 겹치지 않으므로 한 종류가 셀 수보다 많이 돌면 망가진 자료다.
   * 같은 종류의 묶음이 되풀이되어도 남은 수가 새로 차지 않게 종류별로 센다
   */
  const runLeft = new Map<unknown, number>();
  let kind: unknown;
  const eachCell = (start: number, count: number, f: (j: number) => void): void => {
    if (head) return;
    const end = Math.min(out.rows * out.cols, start + count);
    let left = runLeft.get(kind) ?? out.rows * out.cols;
    for (let j = Math.max(0, start); j < end && left > 0; j++, left--) f(j);
    runLeft.set(kind, left);
  };
  const first = next();
  if (!first || typeof first.value !== 'string' || !first.value.startsWith('OPENCAD_TABLE')) return null;
  const out: DecodedTable = { rows: 0, cols: 0, merges: [], aligns: new Map(), spans: new Map() };
  const done = (): DecodedTable => {
    if (!head && out.merges.length) out.merges = keepMerges(out.merges, out.rows, out.cols, out.rows * out.cols);
    return out;
  };
  try {
    while (i < items.length) {
      const at = i;
      const tag = next();
      if (!tag || tag.code !== 1000) break;
      // 묶음을 다 읽은 뒤 자리를 적는다(다음 차례 처음에)
      const mark = () => out.spans.set(String(tag.value), [at, i]);
      kind = tag.value;
      switch (tag.value) {
        case 'size':
          out.rows = int();
          out.cols = int();
          // 셀마다 객체를 만들므로 표로 다루지 않는다(블록 참조로 남는다)
          if (!tableSizeOk(out.rows, out.cols)) return null;
          break;
        case 'rowh': {
          const n = size();
          out.rowHeights = Array.from({ length: n }, real);
          break;
        }
        case 'baseh': {
          const n = size();
          out.baseRowHeights = Array.from({ length: n }, real);
          break;
        }
        case 'colw': {
          const n = size();
          out.colWidths = Array.from({ length: n }, real);
          break;
        }
        case 'kinds': {
          const n = size();
          out.rowKinds = Array.from({ length: n }, () => CODE_KIND[int()] ?? 'data');
          break;
        }
        case 'merge': {
          const n = size();
          for (let k = 0; k < n; k++) out.merges.push({ row: int(), col: int(), rows: int(), cols: int() });
          break;
        }
        case 'align': {
          const n = size();
          for (let k = 0; k < n; k++) {
            const idx = int();
            out.aligns.set(idx, int());
          }
          break;
        }
        case 'text': {
          const n = size();
          out.texts = new Map();
          for (let k = 0; k < n; k++) {
            const idx = int();
            const parts = int();
            let s = '';
            for (let p = 0; p < parts && i < items.length; p++) s += String(next()?.value ?? '');
            out.texts.set(idx, s);
          }
          break;
        }
        case 'fill': {
          const n = int();
          const fills = (out.fills = new Map<number, CadColor | null>());
          for (let k = 0; k < n && i < items.length; k++) {
            const start = int();
            const count = int();
            const aci = int();
            const rgb = int();
            const f: CadColor | null = aci < 0 ? null : rgb >= 0 ? { aci, rgb: rgb & 0xffffff } : { aci };
            // 표 크기 밖(망가진 자료)은 버린다
            eachCell(start, count, (j) => fills.set(j, f && { ...f }));
          }
          break;
        }
        case 'theight': {
          const n = int();
          const heights = (out.heights = new Map<number, number>());
          for (let k = 0; k < n && i < items.length; k++) {
            const start = int();
            const count = int();
            const v = real();
            // 0 이하·숫자가 아닌 높이와 표 크기 밖 번호(망가진 자료)는 버린다
            if (!(Number.isFinite(v) && v > 0)) continue;
            eachCell(start, count, (j) => heights.set(j, v));
          }
          break;
        }
        case 'tcolor': {
          const n = int();
          const colors = (out.colors = new Map<number, CadColor>());
          for (let k = 0; k < n && i < items.length; k++) {
            const start = int();
            const count = int();
            const aci = int();
            const rgb = int();
            if (aci < 0 || aci > 257) continue;
            const c: CadColor = rgb >= 0 ? { aci, rgb: rgb & 0xffffff } : { aci };
            eachCell(start, count, (j) => colors.set(j, { ...c }));
          }
          break;
        }
        case 'tstyle': {
          const n = int();
          const styles = (out.textStyles = new Map<number, string>());
          for (let k = 0; k < n && i < items.length; k++) {
            const start = int();
            const count = int();
            const parts = int();
            let name = '';
            for (let p = 0; p < parts && i < items.length; p++) name += String(next()?.value ?? '');
            // 빈 이름과 표 크기 밖 번호(망가진 자료)는 버린다
            if (!name) continue;
            eachCell(start, count, (j) => styles.set(j, name));
          }
          break;
        }
        case 'lock': {
          const n = int();
          const locks = (out.locks = new Map<number, number>());
          for (let k = 0; k < n && i < items.length; k++) {
            const start = int();
            const count = int();
            const v = int() & 5;
            // 잠금 없음과 표 크기 밖 번호(망가진 자료)는 버린다
            if (!v) continue;
            eachCell(start, count, (j) => locks.set(j, v));
          }
          break;
        }
        default:
          return done();
      }
      mark();
    }
  } catch {
    return done();
  }
  return done();
}

/** 객체의 표 자료. ACAD_TABLE의 행 × 열과 자료 크기가 다르면 쓰지 않는 자료이므로 머리 값만 읽고 셀 묶음을 펼치지 않는다 */
export function tableDataOf(e: Entity): DecodedTable | null {
  const x = e.xdata?.find((q) => q.app.toUpperCase() === TABLE_APP);
  if (e.type !== 'ACAD_TABLE') return decodeTableXData(x);
  const head = decodeTableXData(x, true);
  return head && head.rows === e.rows && head.cols === e.columns ? decodeTableXData(x) : head;
}

/**
 * 겹치는 병합은 앞의 것만 남긴다. 병합의 크기는 파일 값이다. 표 밖으로 나가는 병합은 어차피 쓰지 않으니(tableFromEntity) 칸을 세지 않는다.
 * 첫 충돌에서 멈추고, 훑은 칸이 표 넓이의 몇 배를 넘으면 나머지 병합은 버린다(정상 표의 병합은 겹치지 않는다)
 */
function keepMerges(merges: readonly Merge[], rows: number, cols: number, cells: number): Merge[] {
  const taken = new Set<number>();
  let scan = TABLE_MERGE_RATIO * cells + TABLE_EMPTY_CELLS;
  return merges.filter((m) => {
    if (m.row < 0 || m.col < 0 || m.rows < 1 || m.cols < 1) return false;
    if (rows > 0 && m.row + m.rows > rows) return false;
    if (m.col + m.cols > cols) return false;
    const area = m.rows * m.cols;
    if (area > scan) return false;
    scan -= area;
    for (let r = m.row; r < m.row + m.rows; r++) for (let c = m.col; c < m.col + m.cols; c++) if (taken.has(r * cols + c)) return false;
    for (let r = m.row; r < m.row + m.rows; r++) for (let c = m.col; c < m.col + m.cols; c++) taken.add(r * cols + c);
    return true;
  });
}

/** 셀 문자 스타일 재지정(셀 번호 → 이름)을 확장 자료 tstyle 묶음 항목으로(encodeTableXData와 같은 꼴) */
function textStyleGroup(names: ReadonlyMap<number, string>): XDataItem[] {
  const it: XDataItem[] = [];
  const runs: [number, number, string][] = [];
  for (const [i, n] of [...names].sort((a, b) => a[0] - b[0])) {
    const last = runs[runs.length - 1];
    if (last && last[0] + last[1] === i && last[2] === n) last[1]++;
    else runs.push([i, 1, n]);
  }
  if (!runs.length) return it;
  it.push({ code: 1000, value: 'tstyle' }, { code: 1071, value: runs.length });
  for (const [start, count, name] of runs) {
    const parts = chunks(name);
    it.push({ code: 1071, value: start }, { code: 1071, value: count }, { code: 1071, value: parts.length }, ...parts.map((p) => ({ code: 1000, value: p })));
  }
  return it;
}

/** AcDbTable 원본 태그 안(100 AcDbTable 다음부터 다음 100 전까지)의 자리 [시작, 끝) */
function acdbTableRange(raw: readonly RawTag[] | undefined): [number, number] | null {
  if (!raw) return null;
  const start = raw.findIndex((t) => t.code === 100 && String(t.value).trim() === 'AcDbTable');
  if (start < 0) return null;
  let end = start + 1;
  while (end < raw.length && raw[end]!.code !== 100) end++;
  return [start + 1, end];
}

/**
 * 표가 가리키는 문자 스타일 이름(33차): 확장 자료의 셀 문자 스타일 재지정과 AutoCAD 원본 태그(AcDbTable)의 7(셀·표 수준 문자 스타일).
 * 소거(PURGE)가 쓰이는 문자 스타일로 센다
 */
export function tableTextStyleRefs(e: Entity): string[] {
  if (e.type !== 'ACAD_TABLE' && e.type !== 'INSERT') return [];
  const out = new Set<string>();
  const x = tableDataOf(e);
  for (const n of x?.textStyles?.values() ?? []) out.add(n);
  if (e.type === 'ACAD_TABLE') {
    const r = acdbTableRange(e.raw);
    if (r) for (let k = r[0]; k < r[1]; k++) if (e.raw![k]!.code === 7 && String(e.raw![k]!.value ?? '').trim()) out.add(String(e.raw![k]!.value).trim());
  }
  return [...out];
}

/**
 * 표가 가리키는 문자 스타일 이름을 map으로 바꾼 객체(33차 — 이름 바꾸기·다른 도면으로 복사): 확장 자료의 tstyle 묶음과 원본 태그(AcDbTable)의 7.
 * 다른 값은 그대로. 바뀐 것이 없으면 null
 */
export function mapTableTextStyles<T extends Entity>(e: T, map: (name: string) => string): T | null {
  if (e.type !== 'ACAD_TABLE' && e.type !== 'INSERT') return null;
  let changed = false;
  let xdata = e.xdata;
  const xi = e.xdata?.findIndex((q) => q.app.toUpperCase() === TABLE_APP) ?? -1;
  if (xi >= 0) {
    const x = e.xdata![xi]!;
    const d = tableDataOf(e);
    const span = d?.spans.get('tstyle');
    if (d?.textStyles?.size && span) {
      const names = new Map<number, string>();
      for (const [i, n] of d.textStyles) {
        const m = map(n);
        if (m !== n) changed = true;
        names.set(i, m);
      }
      if (changed) {
        const items = [...x.items.slice(0, span[0]), ...textStyleGroup(names), ...x.items.slice(span[1])];
        xdata = e.xdata!.map((q, k) => (k === xi ? { app: q.app, items } : q));
      }
    }
  }
  let raw = e.type === 'ACAD_TABLE' ? e.raw : undefined;
  const r = e.type === 'ACAD_TABLE' ? acdbTableRange(e.raw) : null;
  if (r && raw) {
    let rawChanged = false;
    const next = raw.map((t, k) => {
      if (k < r[0] || k >= r[1] || t.code !== 7) return t;
      const v = String(t.value ?? '').trim();
      if (!v) return t;
      const m = map(v);
      if (m === v) return t;
      rawChanged = true;
      return { ...t, value: m };
    });
    if (rawChanged) {
      raw = next;
      changed = true;
    }
  }
  if (!changed) return null;
  const out = { ...e, xdata } as T;
  if (raw && out.type === 'ACAD_TABLE') out.raw = raw;
  return out;
}

export interface RawTableCells {
  merges: Merge[];
  aligns: Map<number, number>;
  fills: Map<number, CadColor | null>;
  /** 셀 문자 높이·문자 색 재지정(32차) */
  heights: Map<number, number>;
  colors: Map<number, CadColor>;
  /** 셀 문자 스타일 재지정(33차 — 이름) */
  textStyles: Map<number, string>;
  /** 셀 수(171 개수) */
  count: number;
}

/**
 * AutoCAD 원본 태그(AcDbTable)의 셀 병합·셀 정렬·셀 배경 채우기(31차).
 * 채우기는 셀 재지정 플래그(R2007+ 91 / 그 전 177)의 4(배경색)이면 63 색(283이 0일 때), 2(채우기 없음 여부)와 283이 1이면 채우지 않음 —
 * io/tablecells.ts rawCellOverrides와 같은 판정(셀의 283은 표본 DXF·*T 블록에서 채울 때 0이다).
 * 32차 문자 높이·문자 색: 플래그의 0x20이면 140(셀 수준 문자 높이 재지정, 0보다 클 때), 0x08이면 64(셀 내용 색 재지정 — 색인).
 * 33차 문자 스타일: 플래그의 0x10이면 7(셀 수준 문자 스타일 이름 재지정, 빈 이름은 버린다)
 */
export function rawTableCells(raw: readonly RawTag[] | undefined): RawTableCells {
  const out: RawTableCells = { merges: [], aligns: new Map(), fills: new Map(), heights: new Map(), colors: new Map(), textStyles: new Map(), count: 0 };
  if (!raw) return out;
  const start = raw.findIndex((t) => t.code === 100 && String(t.value).trim() === 'AcDbTable');
  if (start < 0) return out;
  let rows = 0;
  let cols = 0;
  let cell = -1;
  let seen = new Set<number>();
  let span: { w: number; h: number } = { w: 1, h: 1 };
  // 셀 재지정 값(값 묶음 301…304 밖의 첫 값). 문자 스타일(7)은 이름이라 따로
  let ovr = new Map<number, number>();
  let styleName: string | undefined;
  let inValue = false;
  const flush = () => {
    if (cell >= 0 && cols > 0 && (span.w > 1 || span.h > 1)) out.merges.push({ row: Math.floor(cell / cols), col: cell % cols, rows: Math.max(1, span.h), cols: Math.max(1, span.w) });
    if (cell < 0) return;
    const flags = ovr.get(177) ?? ovr.get(91) ?? 0;
    const none = ovr.get(283) ?? 0;
    if (flags & 0x04 && ovr.has(63) && !none) out.fills.set(cell, { aci: ovr.get(63)! });
    else if (flags & 0x02 && none) out.fills.set(cell, null);
    const th = ovr.get(140);
    if (flags & 0x20 && th !== undefined && th > 0) out.heights.set(cell, th);
    const tc = ovr.get(64);
    if (flags & 0x08 && tc !== undefined && tc >= 0 && tc <= 257) out.colors.set(cell, { aci: tc });
    if (flags & 0x10 && styleName) out.textStyles.set(cell, styleName);
  };
  for (let k = start + 1; k < raw.length; k++) {
    const t = raw[k]!;
    if (t.code === 100) break;
    if (cell < 0 && t.code === 92 && !cols) cols = Number(t.value) || 0;
    if (cell < 0 && t.code === 91 && !rows) rows = Number(t.value) || 0;
    if (t.code === 171) {
      flush();
      cell++;
      seen = new Set();
      span = { w: 1, h: 1 };
      ovr = new Map();
      styleName = undefined;
      inValue = false;
      continue;
    }
    if (cell < 0) continue;
    if (t.code === 301) inValue = true;
    else if (t.code === 304) inValue = false;
    else if (!inValue && t.code === 7 && styleName === undefined) styleName = String(t.value ?? '').trim();
    else if (!inValue && (t.code === 177 || t.code === 91 || t.code === 63 || t.code === 283 || t.code === 140 || t.code === 64) && !ovr.has(t.code)) {
      const v = Number(t.value);
      ovr.set(t.code, Number.isFinite(v) ? v : 0);
    }
    if (seen.has(t.code)) continue;
    if (t.code === 175) span.w = Number(t.value) || 1;
    else if (t.code === 176) span.h = Number(t.value) || 1;
    else if (t.code === 170) {
      const a = Number(t.value);
      if (a >= 1 && a <= 9) out.aligns.set(cell, a);
    } else continue;
    seen.add(t.code);
  }
  flush();
  out.count = cell + 1;
  out.merges = keepMerges(out.merges, rows, cols, Math.max(rows * cols, out.count));
  return out;
}

/** 표로 편집할 수 있는 객체인지(ACAD_TABLE, 또는 표 확장 자료가 있는 블록 참조). 빈 곳을 누를 때마다 객체마다 부르므로 머리 값만 본다 */
export function isEditableTable(e: Entity | undefined): e is TableEntity | InsertEntity {
  if (!e) return false;
  if (e.type === 'ACAD_TABLE') return true;
  if (e.type !== 'INSERT' || e.tableTooLarge) return false;
  const d = decodeTableXData(e.xdata?.find((x) => x.app.toUpperCase() === TABLE_APP), true);
  return !!d && d.rows > 0 && d.cols > 0 && !!d.rowHeights && !!d.colWidths;
}

export interface ReadTable {
  data: TableData;
  style: TableStyle;
  styleEntry: TableStyleEntry | null;
}

/** 표 객체에서 표 정의를 읽는다 */
export function tableFromEntity(e: TableEntity | InsertEntity, doc: CadDocument): ReadTable | null {
  if (e.type === 'INSERT' && e.tableTooLarge) return null;
  const x = tableDataOf(e);
  const te = e.type === 'ACAD_TABLE' ? e : null;
  const rows = te ? te.rows : (x?.rows ?? 0);
  const cols = te ? te.columns : (x?.cols ?? 0);
  if (!(rows > 0 && cols > 0)) return null;
  const xok = !!x && x.rows === rows && x.cols === cols;
  const styleEntry = findTableStyle(doc, te?.tableStyle) ?? findTableStyle(doc, 'Standard');
  const style = styleEntry?.style ?? defaultTableStyle(isMetric(doc));
  const pick = (a: number[] | undefined, b: number[] | undefined, n: number, d: number): number[] =>
    Array.from({ length: n }, (_, i) => {
      const v = a?.[i] ?? b?.[i] ?? b?.[b.length - 1];
      return typeof v === 'number' && v > 0 ? v : d;
    });
  const rowHeights = pick(te?.rowHeights, xok ? x!.rowHeights : undefined, rows, 1);
  const colWidths = pick(te?.columnWidths, xok ? x!.colWidths : undefined, cols, 1);
  const baseRowHeights = xok && x!.baseRowHeights?.length === rows ? x!.baseRowHeights.map((v, i) => Math.min(v, rowHeights[i]!)) : [...rowHeights];
  const raw: RawTableCells = te ? rawTableCells(te.raw) : { merges: [], aligns: new Map(), fills: new Map(), heights: new Map(), colors: new Map(), textStyles: new Map(), count: 0 };
  // 원본 태그의 셀 재지정은 셀마다 하나씩 있을 때만(표 크기와 맞지 않으면 어느 셀인지 모른다)
  const rawOk = !xok && raw.count === rows * cols;
  const rawFills = rawOk ? raw.fills : null;
  const cells: CellData[] = Array.from({ length: rows * cols }, (_, i) => {
    // R2007 이전 DXF는 비ASCII 문자를 \U+XXXX로 쓰고 리더는 문자 내용을 그대로 둔다 → 편집할 수 있게 푼다
    const text = decodeCadEscapes(te?.cells?.[i]?.text ?? (xok ? (x!.texts?.get(i) ?? '') : ''));
    const c: CellData = { text };
    const a = xok ? x!.aligns.get(i) : raw.aligns.get(i);
    if (a) c.align = a;
    // 31차 셀 배경 채우기(앱 표는 확장 자료, AutoCAD 표는 셀 재지정 63·283)
    const f = xok ? x!.fills?.get(i) : rawFills?.get(i);
    if (f !== undefined) c.fill = f ? { ...f } : null;
    // 32차 셀 문자 높이·문자 색(앱 표는 확장 자료, AutoCAD 표는 셀 재지정 140·64)
    const th = xok ? x!.heights?.get(i) : rawOk ? raw.heights.get(i) : undefined;
    if (th !== undefined) c.height = th;
    const tc = xok ? x!.colors?.get(i) : rawOk ? raw.colors.get(i) : undefined;
    if (tc) c.color = { ...tc };
    // 33차 셀 문자 스타일(앱 표는 확장 자료, AutoCAD 표는 셀 재지정 7). 도면에 없는 스타일(망가진 자료)은 버려 셀 스타일을 따르고, 이름은 도면의 철자로
    const ts = xok ? x!.textStyles?.get(i) : rawOk ? raw.textStyles.get(i) : undefined;
    const tsDef = ts ? doc.textStyles.get(tableKey(ts)) : undefined;
    if (tsDef?.name) c.textStyle = tsDef.name;
    // 34차 셀 잠금(앱 표는 확장 자료, AutoCAD 표는 DWG R2010+ 셀 상태를 읽은 객체의 셀 — DXF 참조에는 셀 잠금 코드가 없다)
    const lk = (xok ? (x!.locks?.get(i) ?? 0) : (te?.cells?.[i]?.lock ?? 0)) & 5;
    if (lk) c.lock = lk;
    return c;
  });
  let rowKinds: CellKind[];
  if (xok && x!.rowKinds?.length === rows) rowKinds = x!.rowKinds;
  else {
    rowKinds = Array.from({ length: rows }, () => 'data' as CellKind);
    let r = 0;
    if (!style.titleSuppressed && rows > 1) rowKinds[r++] = 'title';
    if (!style.headerSuppressed && rows > r + 1) rowKinds[r] = 'header';
  }
  const merges = (xok ? x!.merges : raw.merges).filter((m) => m.row >= 0 && m.col >= 0 && m.row + m.rows <= rows && m.col + m.cols <= cols && m.rows * m.cols > 1);
  return { data: { rows, cols, rowHeights, baseRowHeights, colWidths, cells, rowKinds, merges }, style, styleEntry };
}

/** 표 정의를 표 객체 값에 옮긴다(원본 태그·DWG 원본은 맞지 않으므로 뺀다) */
export function applyTableData(e: TableEntity, t: TableData, styleHandle: string | undefined): TableEntity {
  const r: TableEntity = { ...e };
  r.rows = t.rows;
  r.columns = t.cols;
  r.rowHeights = [...t.rowHeights];
  r.columnWidths = [...t.colWidths];
  r.cells = t.cells.map((c) => ({ text: c.text }));
  if (styleHandle) r.tableStyle = styleHandle;
  else delete r.tableStyle;
  r.xdata = [...(e.xdata ?? []).filter((x) => x.app.toUpperCase() !== TABLE_APP), encodeTableXData(t)];
  delete r.raw;
  delete r.rawVersion;
  delete r.dwgRaw;
  return r;
}
